/* Cloud, security and compliance platforms that GRC / privacy job posts expect you to understand. */
const TOOLS2 = [
{id:"t-azure",track:"tool",title:"Microsoft Azure and Entra ID",short:"Microsoft's cloud and its identity system: where most Indian enterprises run, and where auditors look",weeks:"Tool 3",prio:true,sk:["azure","cloud","iam"],
 obj:"Explain how Azure is organised, who controls access through Entra ID, and where to find compliance evidence (policy results, Defender for Cloud's regulatory compliance view, activity logs) without being an engineer.",
 why:"Most large Indian employers, IT-services firms and banks' India centres run on Microsoft 365 and Azure. GRC, IT audit and privacy roles ask you to read access reviews, MFA reports and cloud compliance dashboards from Microsoft tools, and AZ-900/SC-900 are common entry certificates.",
 subs:[
  {t:"Cloud in one picture: tenant, subscription, resource group, resource",l:1,b:"A tenant is the company's Microsoft account space (one per organisation). Inside it, subscriptions are billing and permission boxes (e.g. 'Production', 'Test'). Resource groups are folders inside a subscription, and resources are the actual things: virtual machines, databases, storage accounts. Permissions and policies set at a higher box flow down to everything inside.",ex:"LedgerLeaf has one tenant, two subscriptions (Prod, Dev), and a resource group 'customer-portal' holding a web app, a SQL database and a storage account.",v:"Azure tenant subscription resource group explained beginners"},
  {t:"Regions and data residency",l:1,b:"Azure stores data in regions. India has Central India (Pune), South India (Chennai) and West India (Mumbai). Contracts and regulators (RBI payment data rules, client DPAs) often ask where data sits, and the answer is the region chosen for each resource.",ex:"An RBI-regulated fintech checks that its payment database uses Central India and its backups don't replicate outside India.",v:"Azure regions India data residency explained"},
  {t:"Entra ID (formerly Azure AD): who can sign in",l:1,b:"Entra ID is the company's identity directory: every employee account, group and app sign-in lives here. It controls MFA, password rules and single sign-on. When an auditor asks 'show me that leavers lost access', the evidence usually comes from Entra ID sign-in and audit logs.",v:"Microsoft Entra ID explained beginners Azure AD renamed"},
  {t:"Conditional Access: rules for sign-in",l:1,b:"Conditional Access policies are if-then rules: IF a user signs in to email from outside India on an unmanaged device, THEN require MFA or block. Policies can run in 'report-only' mode first, which is a safe way to test. Missing MFA for admins is one of the most common audit findings.",v:"Entra Conditional Access policy tutorial MFA"},
  {t:"Azure RBAC: who can change what",l:1,b:"Role-Based Access Control decides what a signed-in person can do to resources: Reader (look), Contributor (change), Owner (change and grant access). Least privilege means most staff get Reader, a few get Contributor, very few get Owner. Privileged Identity Management (PIM) can make admin rights temporary and approved.",v:"Azure RBAC roles owner contributor reader explained"},
  {t:"Azure Policy: guardrails",l:1,b:"Azure Policy checks resources against rules ('storage must be encrypted', 'only Indian regions allowed') and marks each one compliant or non-compliant. It can also block non-compliant resources from being created. For GRC, policy compliance results are ready-made evidence.",v:"Azure Policy explained compliance tutorial"},
  {t:"Defender for Cloud: the compliance dashboard",l:2,b:"Microsoft Defender for Cloud scores your cloud setup (secure score) and has a regulatory compliance dashboard mapping checks to standards such as the Microsoft cloud security benchmark, ISO 27001, PCI DSS and others you add. Each failing check shows affected resources and how to fix them, and reports can be downloaded as audit evidence.",v:"Defender for Cloud regulatory compliance dashboard tutorial"},
  {t:"Logs: Activity log and sign-in logs",l:2,b:"The Activity log records who changed what in Azure (created, deleted, changed permissions). Entra sign-in logs record every login with time, location, app and result. Both can be sent to a Log Analytics workspace for longer retention and to Microsoft Sentinel for monitoring.",v:"Azure activity log Entra sign-in logs explained"},
  {t:"Key Vault and encryption",l:2,b:"Key Vault stores encryption keys, passwords and certificates so they are not written into code. Most Azure storage is encrypted at rest by default; 'customer-managed keys' means the company controls the key in Key Vault, which some regulators and clients ask for.",v:"Azure Key Vault explained beginners"},
  {t:"Practise for free and certify",l:3,b:"Microsoft Learn's free modules include sandboxes for many exercises. The AZ-900 (Azure Fundamentals) and SC-900 (Security, Compliance and Identity Fundamentals) learning paths are free; the exams are paid, and Microsoft often runs Virtual Training Days with exam discounts. A free Azure account comes with time-limited credit; check current terms and set a budget alert.",v:"AZ-900 full course free"}
 ],
 ill:{type:"stack",title:"How Azure is organised (policies and permissions flow down)",layers:[["Tenant (Entra ID)","Company identity: users, groups, MFA, Conditional Access"],["Management group","Optional: groups subscriptions for shared policy"],["Subscription","Billing and permission boundary, e.g. Production"],["Resource group","Folder, e.g. customer-portal"],["Resource","VM, SQL database, storage account, Key Vault"]]},
 illCap:"Set a rule high up (for example 'India regions only' on the subscription) and everything below inherits it.",
 case:{t:"An ISO 27001 auditor visits a Microsoft shop",b:"The auditor asks for proof of MFA, access reviews and secure configuration. The GRC analyst exports the Conditional Access policy list and an MFA registration report from Entra ID, the quarterly access review results, and the Defender for Cloud regulatory compliance report for ISO 27001 with failing items and remediation tickets. None of this needs coding; it needs knowing where each report lives."},
 ben:["Microsoft 365 and Azure are the most common enterprise stack in India, so evidence requests land here.","AZ-900 and SC-900 are cheap, beginner-friendly certificates recruiters recognise."],
 trap:["Saying 'Azure is secure, so we're compliant': under shared responsibility, settings and access are the customer's job.","Confusing Entra roles (who can manage users) with Azure RBAC (who can change resources).","Treating secure score as a compliance certificate; it is a measure, not an audit opinion."],
 quiz:[
  {q:"Where are employee accounts, MFA and sign-in rules managed?",o:["Azure Policy","Entra ID","Key Vault","Resource group"],a:1,w:"Entra ID (formerly Azure AD) is the identity directory."},
  {q:"A rule that blocks creating storage outside Indian regions is best done with:",o:["Azure Policy","A Conditional Access policy","Key Vault","An Activity log alert only"],a:0,w:"Azure Policy evaluates and can deny resource settings."},
  {q:"Which Azure RBAC role can change resources AND grant access to others?",o:["Reader","Contributor","Owner","Guest"],a:2,w:"Owner can do everything including assigning roles; keep it rare."}],
 refs:[["Microsoft Learn: AZ-900 Azure Fundamentals (free path)","https://learn.microsoft.com/en-us/credentials/certifications/azure-fundamentals/","course"],["Microsoft Learn: SC-900 Security, Compliance and Identity Fundamentals","https://learn.microsoft.com/en-us/credentials/certifications/security-compliance-and-identity-fundamentals/","course"],["Conditional Access overview","https://learn.microsoft.com/en-us/entra/identity/conditional-access/overview","primary"],["Azure Policy overview","https://learn.microsoft.com/en-us/azure/governance/policy/overview","primary"],["Defender for Cloud regulatory compliance dashboard","https://learn.microsoft.com/en-us/azure/defender-for-cloud/regulatory-compliance-dashboard","primary"],["John Savill's Technical Training (YouTube)","https://www.youtube.com/@NTFAQGuy","video"]],
 terms:{"tenant":"A company's own Microsoft cloud space, tied to its Entra ID directory.","subscription":"A billing and permission container for Azure resources.","Entra ID":"Microsoft's identity service (formerly Azure Active Directory).","Conditional Access":"If-then sign-in rules, e.g. require MFA from unknown devices.","RBAC":"Role-based access control: permissions given through roles like Reader or Owner.","Azure Policy":"Rules that check or enforce resource settings.","secure score":"Defender for Cloud's percentage measure of how well settings follow recommendations.","PIM":"Privileged Identity Management: time-limited, approved admin access."}},

{id:"t-aws",track:"tool",title:"AWS for compliance",short:"Amazon Web Services: the most used cloud; learn the services that hold audit evidence",weeks:"Tool 4",prio:true,sk:["aws","cloud","iam"],
 obj:"Explain AWS's shared responsibility model, how IAM and the root account work, and which AWS services produce the evidence GRC teams need (CloudTrail, Config, Security Hub, Audit Manager, Artifact).",
 why:"AWS is the largest cloud provider and runs most Indian start-ups and SaaS firms. SOC 2, ISO 27001 and client security questionnaires at these companies ask cloud questions, and GRC analysts are expected to know where the answers come from. The AWS Certified Cloud Practitioner is a common entry certificate.",
 subs:[
  {t:"Shared responsibility, AWS edition",l:1,b:"AWS secures the cloud itself (data centres, hardware, the network). The customer secures what they put in it: data, accounts, settings, operating systems on servers they run. Every AWS compliance answer starts with 'which side of the line is this?'",ex:"A leaked customer file from a public S3 bucket is the customer's failure, not AWS's.",v:"AWS shared responsibility model explained"},
  {t:"Accounts, regions and Organizations",l:1,b:"An AWS account is a container for resources and bills; companies use many accounts (prod, dev, logging) grouped under AWS Organizations, which can apply guardrails called service control policies (SCPs). India has the Mumbai (ap-south-1) and Hyderabad (ap-south-2) regions, relevant for data-localisation questions.",v:"AWS Organizations accounts SCP explained beginners"},
  {t:"IAM and the root user",l:1,b:"IAM (Identity and Access Management) defines users, groups and roles and attaches policies saying what each may do. The root user owns the account and can do anything; best practice is MFA on root and never using it day to day. Companies increasingly use IAM Identity Center for single sign-on instead of long-lived IAM users.",v:"AWS IAM users roles policies explained beginners"},
  {t:"Reading an IAM policy",l:2,b:"Policies are JSON with Effect (Allow/Deny), Action (e.g. s3:GetObject), Resource (which bucket) and optional Condition. An explicit Deny beats any Allow; anything not allowed is denied by default. '*' means everything, a red flag in reviews.",ex:"{\"Effect\":\"Allow\",\"Action\":\"s3:*\",\"Resource\":\"*\"} gives full control of every bucket: too broad for an analyst.",v:"how to read AWS IAM policy JSON effect action resource"},
  {t:"S3 storage and public exposure",l:1,b:"S3 stores files in buckets. Most cloud data leaks come from buckets accidentally made public. Block Public Access settings (on by default for new buckets) stop this; encryption at rest is on by default for new objects. Reviewers check both, plus who can read the bucket.",v:"S3 block public access encryption explained"},
  {t:"CloudTrail: who did what",l:1,b:"CloudTrail records API activity: who created, changed or deleted what, from where and when. It is the first evidence for investigations and for change-management controls. A trail stored in a separate, locked logging account keeps logs safe from tampering.",v:"AWS CloudTrail explained beginners"},
  {t:"Config and conformance packs: is it set up right?",l:2,b:"AWS Config records resource settings over time and evaluates them against rules ('EBS volumes encrypted', 'root MFA enabled'). Conformance packs bundle rules for a framework. Results show compliant/non-compliant resources with history, which is strong evidence that a control operated over a period.",v:"AWS Config rules conformance packs tutorial"},
  {t:"Security Hub and GuardDuty",l:2,b:"Security Hub collects findings and runs checks against standards such as the AWS Foundational Security Best Practices and CIS AWS Foundations Benchmark, giving a score per standard. GuardDuty watches logs for threats (unusual logins, crypto-mining). GRC teams track Security Hub scores and open findings as metrics.",v:"AWS Security Hub GuardDuty explained"},
  {t:"Audit Manager and Artifact",l:2,b:"AWS Artifact is where you download AWS's own compliance reports (SOC 2, ISO certificates, PCI attestation) for your vendor file, and accept agreements. Audit Manager collects evidence from your accounts automatically against frameworks and helps prepare audit-ready reports.",v:"AWS Artifact Audit Manager explained"},
  {t:"Practise safely and certify",l:3,b:"AWS Skill Builder has free courses, including Cloud Practitioner Essentials. New accounts get free-tier credits; check the current terms, turn on MFA for root immediately and set a billing alarm before trying anything. The Cloud Practitioner exam (CLF-C02) covers cloud concepts, security and compliance, services, and billing.",v:"AWS Cloud Practitioner CLF-C02 full course"}
 ],
 ill:{type:"compare",left:["AWS secures (of the cloud)","Data centres and guards","Hardware and global network","Virtualisation layer","Managed service internals"],right:["You secure (in the cloud)","Your data and its encryption","IAM users, roles and MFA","Bucket, network and logging settings","Operating systems you run (EC2)"]},
 illCap:"The shared responsibility line. Most audit questions are about the right-hand column.",
 case:{t:"A SOC 2 questionnaire at a SaaS start-up",b:"A US client asks: Is root protected by MFA? Are logs retained 12 months? Are S3 buckets private and encrypted? The analyst answers each with evidence: an IAM credential report, the CloudTrail configuration and log bucket lifecycle rule, a Config rule history showing all buckets compliant, and AWS's own SOC 2 report from Artifact for the physical controls."},
 ben:["AWS keywords appear across SaaS, start-up and IT-services GRC posts.","Knowing which service holds which evidence makes you useful in audits from day one."],
 trap:["Asking AWS for your audit logs: AWS gives you the tools, but CloudTrail is yours to configure and keep.","Using '*' in permissions 'temporarily'.","Leaving root without MFA or with access keys."],
 quiz:[
  {q:"Which service records who deleted a database last Tuesday?",o:["AWS Artifact","CloudTrail","GuardDuty","S3"],a:1,w:"CloudTrail logs API activity: who did what, when, from where."},
  {q:"Where do you download AWS's own SOC 2 report for your vendor file?",o:["AWS Artifact","AWS Config","IAM","Security Hub"],a:0,w:"AWS Artifact provides AWS's compliance reports and agreements."},
  {q:"In an IAM policy, an explicit Deny and an Allow conflict. What wins?",o:["Allow","Deny","Whichever is newer","The root user decides"],a:1,w:"An explicit Deny always overrides an Allow."}],
 refs:[["AWS shared responsibility model","https://aws.amazon.com/compliance/shared-responsibility-model/","primary"],["AWS Certified Cloud Practitioner","https://aws.amazon.com/certification/certified-cloud-practitioner/","course"],["AWS Skill Builder (free courses)","https://skillbuilder.aws/","course"],["What is AWS Security Hub?","https://docs.aws.amazon.com/securityhub/latest/userguide/what-is-securityhub.html","primary"],["AWS Artifact","https://aws.amazon.com/artifact/","primary"],["AWS Free Tier update (July 2025)","https://aws.amazon.com/about-aws/whats-new/2025/07/aws-free-tier-credits-month-free-plan/","primary"]],
 terms:{"IAM":"Identity and Access Management: who can do what in AWS.","root user":"The all-powerful owner login of an AWS account.","S3 bucket":"A storage container for files in AWS.","CloudTrail":"AWS's record of actions taken in an account.","AWS Config":"Records and checks resource settings over time.","SCP":"Service control policy: an organisation-wide guardrail on what accounts may do.","Security Hub":"AWS's dashboard of security findings and standard checks.","AWS Artifact":"Portal for AWS's own compliance reports and agreements."}},

{id:"t-purview",track:"tool",title:"Microsoft Purview (data protection and compliance)",short:"Labels, DLP, retention, eDiscovery and Compliance Manager inside Microsoft 365",weeks:"Tool 5",prio:true,sk:["purview","privops","crypto"],
 obj:"Explain how Purview finds sensitive data, labels it, stops it leaking (DLP), keeps or deletes it (retention), finds it for legal and DSAR requests (eDiscovery, audit), and tracks regulatory progress (Compliance Manager).",
 why:"Purview is where privacy law meets the tools most Indian companies already pay for. Big 4 data-protection teams (for example EY's Purview roles) and enterprise privacy jobs ask for DLP, sensitivity labels, retention and eDiscovery skills, and SC-900/SC-401 are the matching certificates. For a lawyer, it is the most natural technical tool to learn.",
 subs:[
  {t:"What Purview is",l:1,b:"Microsoft Purview is the family of data security, governance and compliance tools in Microsoft 365 (and beyond), run from the Purview portal. Think of it as the privacy team's control room for email, Teams, SharePoint, OneDrive and laptops.",v:"Microsoft Purview overview beginners"},
  {t:"Sensitive information types and classifiers",l:1,b:"Purview recognises sensitive data using patterns (sensitive information types, e.g. credit card numbers, Aadhaar-like or PAN-like formats, passport numbers), trainable classifiers (e.g. 'resumes', 'contracts') and exact data match against a list. Data classification shows where such data sits across the company, a head start for a data map.",ex:"A report shows 4,200 files in OneDrive containing PAN-number patterns, 300 shared externally.",v:"Purview sensitive information types trainable classifiers explained"},
  {t:"Sensitivity labels",l:1,b:"Labels such as Public, Internal, Confidential and Restricted are tags on emails and documents. A label can add encryption (only staff can open), watermarks, and block forwarding. Labels can be applied by users, by default, or automatically when sensitive data is detected. They put your classification policy into practice.",v:"Microsoft Purview sensitivity labels tutorial"},
  {t:"Data Loss Prevention (DLP)",l:1,b:"DLP policies watch for sensitive data leaving where it should stay: email to outside addresses, sharing links, uploads from laptops, copy to USB. Actions range from audit only, to warning the user with a policy tip (allowing override with a reason), to blocking. Start in simulation mode, review false alarms, then enforce.",ex:"Rule: if an email to an external domain contains 10+ PAN numbers, block and notify the privacy team; 1–9, warn and allow with justification.",v:"Microsoft Purview DLP policy tutorial"},
  {t:"Retention and records",l:1,b:"Retention policies and labels keep content for a set period then delete it, or keep it as a record that cannot be changed. This is how storage-limitation duties (DPDP, GDPR) and legal retention duties (tax, RBI, SEBI) are enforced in Microsoft 365, including disposition review before deletion.",v:"Purview retention policies labels records management tutorial"},
  {t:"eDiscovery, audit and DSARs",l:2,b:"eDiscovery searches mailboxes, Teams and files for content (by person, keyword, date), places legal holds, and exports results for review. Audit logs show who accessed or shared what. Privacy teams use eDiscovery searches to find a person's data when answering access requests and litigation holds.",v:"Microsoft Purview eDiscovery tutorial data subject request"},
  {t:"Compliance Manager",l:2,b:"Compliance Manager turns regulations into assessments of improvement actions, some tested automatically from Microsoft 365 settings, with a compliance score. A baseline template is included; most regulation templates are premium, so check the regulations list and licence before promising, for example, a DPDP or GDPR assessment.",v:"Microsoft Purview Compliance Manager tutorial"},
  {t:"Insider risk and DSPM for AI",l:3,b:"Insider risk management flags risky patterns (a leaver downloading large volumes). Data Security Posture Management for AI shows sensitive data flowing into Copilot and other AI apps, a new area job posts now mention.",v:"Purview insider risk management DSPM for AI"},
  {t:"Certify",l:3,b:"SC-900 covers Purview at fundamentals level. SC-401 (Information Security Administrator), which replaced SC-400, covers information protection, DLP and retention, and risks and alerts in depth.",v:"SC-401 information security administrator course"}
 ],
 ill:{type:"flow",steps:[["Find","Sensitive info types and classifiers scan files and mail"],["Label","Confidential: encrypt, watermark"],["Protect","DLP warns or blocks external sharing"],["Keep or delete","Retention: 8 years for tax, delete marketing data after 2"],["Prove","Audit log, eDiscovery, Compliance Manager score"]]},
 illCap:"Purview's job in five verbs. Each maps to a privacy duty: data mapping, security safeguards, storage limitation and accountability.",
 case:{t:"DPDP readiness in Microsoft 365",b:"A fintech's DPO asks: where is customer PAN data, who shares it outside, and do we delete old KYC files? The analyst runs data classification for PAN and Aadhaar patterns, proposes labels (Confidential – Customer), pilots a DLP policy in simulation for two weeks (finding most alerts come from a legitimate auditor domain, which is then allowed), and sets retention to delete closed-account KYC after the legal period, with disposition review by Legal."},
 ben:["The most law-adjacent technical tool; DLP, labels and retention are privacy duties in tool form.","Listed by Big 4 data-protection practices and enterprise privacy teams."],
 trap:["Turning DLP straight to 'block' and stopping the business on day one.","Calling labels 'encryption' when a label may only add a tag.","Assuming Compliance Manager templates are free or exist for every law."],
 quiz:[
  {q:"Which Purview feature stops an employee emailing a file of PAN numbers outside the company?",o:["Retention policy","Data Loss Prevention","eDiscovery","Compliance Manager"],a:1,w:"DLP detects sensitive data leaving and can warn or block."},
  {q:"Enforcing 'delete marketing data after 2 years' in Microsoft 365 uses:",o:["Sensitivity labels","Retention policies or labels","Conditional Access","Insider risk"],a:1,w:"Retention keeps then deletes content on schedule."},
  {q:"Best first mode for a new DLP policy:",o:["Block everything","Simulation / audit only","Delete matching files","Disable logging"],a:1,w:"Simulate, review false positives, then enforce."}],
 refs:[["Microsoft Purview documentation","https://learn.microsoft.com/en-us/purview/purview","primary"],["Learn about sensitivity labels","https://learn.microsoft.com/en-us/purview/sensitivity-labels","primary"],["Learn about data loss prevention","https://learn.microsoft.com/en-us/purview/dlp-learn-about-dlp","primary"],["Compliance Manager templates and regulations","https://learn.microsoft.com/en-us/purview/compliance-manager-templates","primary"],["SC-900 learning path","https://learn.microsoft.com/en-us/credentials/certifications/security-compliance-and-identity-fundamentals/","course"],["Microsoft Mechanics (YouTube)","https://www.youtube.com/@MSFTMechanics","video"]],
 terms:{"SIT":"Sensitive information type: a pattern Purview recognises, like a card number.","sensitivity label":"A tag on a file or email that can add protection like encryption.","DLP":"Data Loss Prevention: rules that stop sensitive data leaving.","policy tip":"A warning shown to the user when DLP matches.","retention label":"A tag that keeps content for a set time, then deletes or reviews it.","eDiscovery":"Searching, holding and exporting content for legal or DSAR purposes.","legal hold":"Preserving content so it can't be deleted during a dispute."}},

{id:"t-sentinel",track:"tool",title:"Microsoft Sentinel and SIEM (with Splunk)",short:"Where security logs are collected, searched and turned into alerts",weeks:"Tool 6",sk:["siem","incident","threats"],
 obj:"Explain what a SIEM does, read and write simple KQL queries in Microsoft Sentinel, understand analytics rules, incidents and workbooks, and map the same ideas to Splunk.",
 why:"Security operations, cyber risk and many GRC roles reference SIEM: auditors ask whether logs are collected and reviewed, CERT-In requires 180-day log retention in India, and incident clocks depend on detection. Sentinel is Microsoft's SIEM and is common at Big 4 cyber practices and Microsoft-stack companies; Splunk is the other name you'll see most.",
 subs:[
  {t:"What a SIEM is",l:1,b:"A Security Information and Event Management system collects logs from many sources (sign-ins, firewalls, servers, cloud) into one place, searches them, and raises alerts when patterns look like attacks. Without one, an incident team is reading thousands of separate files.",v:"what is SIEM explained simply"},
  {t:"Sentinel's building blocks",l:1,b:"Data connectors bring logs in (Entra ID, Microsoft 365, AWS, firewalls). Logs land in tables in a Log Analytics workspace. Analytics rules run queries on a schedule and create alerts; related alerts become incidents for analysts. Workbooks are dashboards; playbooks (Logic Apps) automate responses. Microsoft is moving Sentinel into the Defender portal; management in the Azure portal is scheduled to end on 31 March 2027.",v:"Microsoft Sentinel overview tutorial beginners"},
  {t:"KQL: reading a query",l:1,b:"Kusto Query Language reads top to bottom, with each | passing results to the next step. SigninLogs | where ResultType != \"0\" | summarize count() by UserPrincipalName means: take sign-in logs, keep failures, count them per user. You can read most detection rules once you know where, summarize, project, sort and take.",ex:"SigninLogs | where TimeGenerated > ago(1d) | where Location != \"IN\" | project TimeGenerated, UserPrincipalName, Location, IPAddress",v:"KQL tutorial beginners Microsoft Sentinel"},
  {t:"Common tables",l:2,b:"SigninLogs (Entra sign-ins), AuditLogs (directory changes), OfficeActivity (Microsoft 365 actions), SecurityAlert and SecurityIncident, AzureActivity (cloud changes), CommonSecurityLog and Syslog (firewalls, Linux). Knowing which table holds which evidence answers most audit questions about logging.",v:"Sentinel tables SigninLogs AuditLogs OfficeActivity"},
  {t:"Analytics rules and tuning",l:2,b:"A rule is a saved query plus a schedule, a threshold and entity mapping (user, IP, host). Too sensitive and analysts drown in false positives; too loose and attacks pass. Tuning (excluding known-good sources, adjusting thresholds) is continuous and should be documented as a change.",v:"Sentinel analytics rule create tutorial"},
  {t:"Incidents and the response clock",l:1,b:"An incident has severity, owner, status and a timeline of alerts and evidence. The time from first malicious event to detection, and from detection to containment, are key metrics (MTTD, MTTR) and feed regulatory clocks like CERT-In's 6 hours.",v:"Microsoft Sentinel incident investigation walkthrough"},
  {t:"Retention, cost and compliance",l:2,b:"Logs cost money to store, so teams choose what to collect and for how long. CERT-In's 2022 directions require ICT system logs to be kept for 180 days within India; contracts and PCI DSS have their own needs. GRC checks that the retention settings and the log sources match these duties.",v:"Sentinel log retention cost data lake"},
  {t:"Splunk in one page",l:2,b:"Splunk does the same job with its own language, SPL: index=auth action=failure | stats count by user is the KQL summarize equivalent. Splunk Enterprise Security adds correlation searches (like analytics rules) and notables (like alerts). Splunk's free training and Boss of the SOC datasets are good practice.",v:"Splunk SPL tutorial beginners"},
  {t:"Practise and certify",l:3,b:"Microsoft's Log Analytics demo workspace (aka.ms/LADemo, needs a free Azure sign-in) and the Kusto Detective Agency game are free ways to practise KQL. SC-200 (Security Operations Analyst) is the associate certificate; SC-900 introduces Sentinel at fundamentals level.",v:"SC-200 Microsoft security operations analyst full course"}
 ],
 ill:{type:"flow",steps:[["Sources","Entra sign-ins, M365, AWS, firewalls"],["Connectors","Bring logs into the workspace"],["Tables","SigninLogs, AuditLogs, OfficeActivity"],["Analytics rule","KQL query every 5 min"],["Incident","Owner, severity, timeline"],["Response","Playbook disables user; report clocks start"]]},
 illCap:"From raw logs to a handled incident. GRC asks whether each step exists, is documented and works.",
 case:{t:"Brute force at 2 a.m.",b:"An analytics rule counts failed sign-ins per IP over 10 minutes. At 02:04 it fires: 40 failures from one foreign IP across 12 users, then one success. Sentinel opens a high-severity incident; a playbook disables the account and resets sessions. The GRC analyst's role afterwards: confirm the rule and playbook are documented, check the timeline against the CERT-In 6-hour clock, and record the lessons learned."},
 ben:["SIEM appears in SOC, cyber risk and IT audit posts; knowing KQL basics sets you apart from other law graduates.","Helps you test logging and monitoring controls in ISO 27001 (A.8.15–A.8.16) and SOC 2 audits."],
 trap:["Assuming 'logs are collected' means 'logs are reviewed'.","Ignoring retention: a perfect alert is useless if logs needed for the investigation were deleted after 30 days.","Copying detection rules without tuning them."],
 quiz:[
  {q:"In KQL, which operator counts rows per user?",o:["where","summarize count() by","project","take"],a:1,w:"summarize ... by groups and aggregates."},
  {q:"A saved query that runs on a schedule and raises alerts in Sentinel is a(n):",o:["Workbook","Analytics rule","Data connector","Playbook"],a:1,w:"Analytics rules detect; workbooks visualise; playbooks automate."},
  {q:"Under CERT-In's 2022 directions, logs must be kept for:",o:["30 days","90 days","180 days within India","7 years"],a:2,w:"180 days, maintained within Indian jurisdiction."}],
 refs:[["What is Microsoft Sentinel?","https://learn.microsoft.com/en-us/azure/sentinel/overview","primary"],["KQL learning resources (LADemo, Kusto Detective Agency)","https://learn.microsoft.com/en-us/kusto/query/kql-learning-resources","course"],["Kusto Detective Agency","https://detective.kusto.io/","course"],["Sentinel transition to Defender portal: new timeline (Help Net Security)","https://www.helpnetsecurity.com/?p=355468","guide"],["SC-200 Security Operations Analyst","https://learn.microsoft.com/en-us/credentials/certifications/security-operations-analyst/","course"],["Splunk training","https://www.splunk.com/en_us/training.html","course"]],
 terms:{"SIEM":"Security Information and Event Management: central log search and alerting.","KQL":"Kusto Query Language, used in Sentinel and Log Analytics.","SPL":"Splunk's Search Processing Language.","analytics rule":"A scheduled query in Sentinel that creates alerts.","incident":"A grouped set of alerts assigned to an analyst.","playbook":"An automated response (Logic App) triggered by an alert.","MTTD / MTTR":"Mean time to detect / to respond.","workspace":"The Log Analytics store where Sentinel's logs live."}},

{id:"t-grcauto",track:"tool",title:"Compliance automation and GRC platforms (Vanta, Drata, Archer, AuditBoard)",short:"The tools that collect evidence automatically and run audits at scale",weeks:"Tool 7",sk:["grcauto","audit","soc2"],
 obj:"Explain how compliance-automation tools (Vanta, Drata) connect to systems and test controls continuously, how enterprise GRC platforms (Archer, MetricStream, AuditBoard) organise risks, controls and audits, and how Jira fits into remediation.",
 why:"Start-up and SaaS GRC posts commonly ask for hands-on experience with Vanta, Drata, TrustCloud or OneTrust, plus Jira; enterprise and banking posts name Archer, MetricStream or AuditBoard. Employers also increasingly mention AI-enabled GRC tooling. You don't need every tool; you need the shared model so you can learn any of them in a week.",
 subs:[
  {t:"Two families of tools",l:1,b:"Compliance automation (Vanta, Drata, Secureframe, Sprinto, Scrut) connects to cloud, HR and code systems to test controls automatically for SOC 2, ISO 27001, HIPAA and more; popular with start-ups. Enterprise GRC platforms (Archer, MetricStream, ServiceNow IRM, AuditBoard) handle risk registers, control testing, audits and issues across large organisations, with heavier configuration.",v:"Vanta vs Drata vs Archer GRC tools explained"},
  {t:"Integrations and automated tests",l:1,b:"The tool connects (read-only) to AWS/Azure, Google Workspace or Entra ID, the HR system, GitHub and laptops' device management. It then runs tests like 'all employees have MFA', 'laptops encrypted', 'leavers removed within 3 days'. A failing test shows which people or resources fail, so you fix the cause rather than collect screenshots.",ex:"Test fails: 3 of 58 employees have no MFA. The analyst messages the 3 owners and the test turns green the next day.",v:"Vanta automated tests integrations demo"},
  {t:"Controls, frameworks and mapping",l:1,b:"One control (e.g. 'MFA on all accounts') maps to many frameworks: SOC 2 CC6.1, ISO 27001 A.5.17/A.8.5, HIPAA safeguards. Tools hold these mappings so one piece of evidence counts everywhere; you still need to check the control fits your company.",v:"control mapping SOC 2 ISO 27001 one control many frameworks"},
  {t:"Evidence, policies and people tasks",l:1,b:"Not everything is automated. Policies come as templates you adapt and get approved; people tasks (accept policies, complete training, background checks) are tracked per employee; manual evidence (board minutes, vendor reviews) is uploaded with owners and due dates. An evidence library with freshness dates is the core of audit readiness.",v:"Drata policies evidence personnel tasks demo"},
  {t:"Audits inside the tool",l:2,b:"Auditors can be given access to view controls and evidence directly, which shortens audits. Observation windows matter: a SOC 2 Type II examines whether controls worked over a period (often 3–12 months), so continuous green tests over time are what count.",v:"SOC 2 Type 2 audit with Vanta Drata what auditors see"},
  {t:"Trust centres and questionnaires",l:2,b:"Trust centre pages share security documents with customers (sometimes under NDA). Questionnaire tools answer client security questionnaires from a library of approved answers, increasingly with AI drafting that a human must check.",v:"trust center security questionnaire automation"},
  {t:"Enterprise GRC: Archer, MetricStream, AuditBoard",l:2,b:"These platforms model the organisation (business units, processes, assets), then link risks, controls, tests, issues and audits, with workflows and approvals. Analysts mostly work lists, forms, assessments and reports, much like ServiceNow IRM. AuditBoard is strong with internal audit and SOX teams.",v:"Archer GRC platform demo overview"},
  {t:"Jira for remediation",l:1,b:"Fixes happen where engineers work. Findings become Jira tickets with an owner, due date and link back to the control; the GRC tool or a dashboard tracks closure. Writing a clear ticket (what is wrong, why it matters, what 'done' looks like) is a core analyst skill.",ex:"Title: Enforce MFA for 3 users without it (SOC 2 CC6.1). Done when: test 'MFA enabled' passes for all active users.",v:"Jira tutorial beginners create issue"},
  {t:"How to get hands-on",l:3,b:"Vendors offer demos and product tours; Vanta and Drata publish free guides on SOC 2 and ISO 27001. Build the same model yourself in a spreadsheet (controls, tests, evidence, owners, status) and say so on your resume: 'built a control and evidence tracker mirroring compliance-automation workflows'.",v:"build your own GRC evidence tracker spreadsheet"}
 ],
 ill:{type:"flow",steps:[["Connect","Cloud, HR, identity, code, laptops"],["Test","MFA on? Disk encrypted? Leavers removed?"],["Fix","Jira ticket to the owner"],["Evidence","Auto-collected plus uploads, with dates"],["Audit","Auditor views controls over the period"]]},
 illCap:"How compliance automation replaces screenshot-hunting with continuous checks.",
 case:{t:"A 90-person SaaS gets SOC 2 in five months",b:"The company connects AWS, Google Workspace, its HR system and GitHub to a compliance-automation tool. 61% of tests pass on day one. The GRC analyst triages failures into Jira, adapts 14 policy templates for leadership approval, chases training completion, and uploads quarterly access-review evidence. After a 3-month observation window with tests staying green, the auditor reviews evidence in the tool and issues the Type II report."},
 ben:["Vanta/Drata/Jira experience is a frequent ask in SaaS GRC posts.","The control → test → evidence model transfers to every GRC platform."],
 trap:["Believing 'the tool says 100%' equals compliance; tests only check what they are built to check.","Uploading stale evidence (last year's access review).","Adopting template policies the company doesn't follow."],
 quiz:[
  {q:"What does a compliance-automation integration with the identity provider let the tool do?",o:["Write policies","Test things like MFA for every user automatically","Sign the audit report","Replace the auditor"],a:1,w:"It reads settings to run automated control tests."},
  {q:"SOC 2 Type II looks at whether controls:",o:["Exist on one day","Operated effectively over a period","Are written in Jira","Are cheap"],a:1,w:"Type II covers operating effectiveness over an observation window."},
  {q:"A good remediation ticket must include:",o:["Only the control number","What's wrong, why it matters, owner, due date and what 'done' looks like","The auditor's name","A screenshot only"],a:1,w:"Clear tickets get fixed; vague ones linger."}],
 refs:[["Vanta resources (SOC 2, ISO 27001 guides)","https://www.vanta.com/resources","guide"],["Drata GRC Central","https://drata.com/grc-central","guide"],["Atlassian: Jira tutorials","https://www.atlassian.com/software/jira/guides","course"],["eSecurity Planet: top GRC tools 2026","https://www.esecurityplanet.com/products/top-grc-vendors.html","guide"]],
 terms:{"compliance automation":"Software that tests controls automatically through integrations.","integration":"A read-only connection from the tool to a system like AWS or the HR app.","automated test":"A continuous check such as 'all users have MFA'.","observation window":"The period a SOC 2 Type II auditor examines.","trust centre":"A page sharing security documents with customers.","Archer / MetricStream / AuditBoard":"Enterprise GRC platforms for risks, controls and audits.","Jira":"Atlassian's ticketing tool used to track remediation work."}},

{id:"t-vuln",track:"tool",title:"Vulnerability management tools (Qualys, Tenable, Defender)",short:"Scanners find weaknesses; GRC sets deadlines, tracks fixes and handles exceptions",weeks:"Tool 8",sk:["vuln","threats","risk"],
 obj:"Read a vulnerability scan report, prioritise findings using severity, exploitation and exposure, apply remediation SLAs, and manage risk-accepted exceptions with proper approval.",
 why:"Patching and vulnerability metrics appear in almost every audit (ISO 27001 A.8.8, SOC 2, PCI DSS, RBI and SEBI cyber frameworks) and board report. Cyber risk and GRC posts mention Qualys, Tenable/Nessus, Rapid7 or Microsoft Defender Vulnerability Management. GRC owns the policy, the SLAs, the exceptions and the reporting.",
 subs:[
  {t:"Vulnerability, scan and finding",l:1,b:"A vulnerability is a weakness, often a known software flaw with a CVE number (e.g. CVE-2024-3400). A scanner (Qualys, Tenable Nessus, Rapid7, Defender) checks systems for known weaknesses and produces findings: which host, which flaw, how severe, how to fix.",v:"vulnerability scanning explained beginners CVE"},
  {t:"Severity: CVSS",l:1,b:"CVSS gives a 0–10 base score: Critical 9.0–10, High 7.0–8.9, Medium 4.0–6.9, Low 0.1–3.9. It measures how bad a flaw could be in general, not how risky it is for you.",v:"CVSS score explained simply"},
  {t:"Real-world risk: KEV, EPSS and exposure",l:1,b:"CISA's Known Exploited Vulnerabilities catalogue lists flaws attackers are actually using; EPSS estimates the chance of exploitation soon. Combine these with exposure (internet-facing or internal?) and asset importance (payment system or test box?). A High on an internet-facing server in KEV beats a Critical on an isolated lab machine.",v:"CISA KEV EPSS vulnerability prioritization explained"},
  {t:"Remediation SLAs",l:1,b:"A vulnerability management policy sets fix deadlines by priority, for example Critical 15 days, High 30, Medium 90, Low 180 (each company sets its own; PCI DSS expects critical security patches within one month of release). The key metric is the percentage fixed within SLA, plus the age of overdue items.",v:"vulnerability remediation SLA policy metrics"},
  {t:"Reading a scan report",l:2,b:"Look for: host/asset, finding title and CVE, severity, first seen and last seen dates, status (new, active, fixed, reopened), and the solution (usually 'update to version X'). 'First seen' versus today tells you whether it is overdue.",v:"Qualys vulnerability report explained walkthrough"},
  {t:"Exceptions and risk acceptance",l:2,b:"Sometimes a fix can't happen in time (a vendor system that breaks if patched). The exception needs a business reason, compensating controls (isolate the server, extra monitoring), a risk owner's approval at the right level, and an expiry date. Exceptions without expiry are a classic audit finding.",ex:"Exception: legacy billing server can't take patch until vendor upgrade in March; compensating controls: firewall allows only the app server; approved by CTO; expires 31 March.",v:"vulnerability exception risk acceptance process"},
  {t:"Coverage: are we scanning everything?",l:2,b:"A clean report means nothing if half the servers aren't scanned. Compare the scanner's asset list with the asset inventory or cloud account list; unscanned assets are a finding. Authenticated scans (with login) find far more than unauthenticated ones.",v:"vulnerability scan coverage authenticated vs unauthenticated"},
  {t:"Reporting to management",l:2,b:"Good monthly metrics: open Criticals/Highs by business unit, % fixed within SLA, overdue count and age, KEV items open, exceptions active and expiring, scan coverage %. Trend lines beat snapshots.",v:"vulnerability management dashboard metrics KPI"},
  {t:"Practise",l:3,b:"Tenable offers a free, limited Nessus Essentials edition for personal learning (check current IP limits and licence terms; they have changed). Qualys has a free Community Edition. Practise on your own lab machines only; scanning systems you don't own or have permission for may be illegal.",v:"Nessus Essentials install scan home lab"}
 ],
 ill:{type:"table",head:["Host","Finding","CVSS","KEV","Exposure","Priority","SLA"],rows:[["web-01","Firewall OS flaw (CVE)","10.0","Yes","Internet","P1","7 days"],["app-02","OpenSSL update","7.5","No","Internal","P2","30 days"],["hr-laptop-14","Browser update","8.8","Yes","User device","P1","15 days"],["lab-07","Old Java","9.8","No","Isolated","P3","90 days"]]},
 illCap:"Priority comes from severity plus exploitation plus exposure, not CVSS alone.",
 case:{t:"Monthly vulnerability review at a payments company",b:"The scanner shows 12 Criticals. The GRC analyst checks KEV: 3 are actively exploited and internet-facing, so they become P1 with 7-day targets and an escalation to the CTO. Two others sit on a legacy server whose exception expired last week; the analyst reopens the exception for re-approval. Coverage is 91%: 14 new cloud servers were never added to scanning, now raised as a finding."},
 ben:["Vulnerability SLAs and exceptions are evidence in nearly every audit you'll support.","Gives you numbers for board and RBI/SEBI reporting."],
 trap:["Prioritising only by CVSS.","Exceptions with no expiry or approved by the wrong person.","Reporting 'zero Criticals' without checking scan coverage."],
 quiz:[
  {q:"Which finding should usually be fixed first?",o:["CVSS 9.8 on an isolated lab PC","CVSS 8.1, in CISA KEV, on an internet-facing server","CVSS 5.0 on a printer","All at once in alphabetical order"],a:1,w:"Active exploitation plus internet exposure beats a higher score in isolation."},
  {q:"A valid risk-accepted exception needs:",o:["Only the engineer's agreement","Reason, compensating controls, right-level approval and an expiry date","Nothing if the server is old","A new CVE number"],a:1,w:"All four elements make it auditable."},
  {q:"'Zero Criticals open' could still hide a problem if:",o:["Scan coverage is incomplete","The report is in PDF","It's Friday","CVSS was used"],a:0,w:"Unscanned assets mean unknown vulnerabilities."}],
 refs:[["FIRST: CVSS","https://www.first.org/cvss/","primary"],["CISA Known Exploited Vulnerabilities catalogue","https://www.cisa.gov/known-exploited-vulnerabilities-catalog","primary"],["FIRST: EPSS","https://www.first.org/epss/","primary"],["NIST National Vulnerability Database","https://nvd.nist.gov/","primary"],["Tenable Nessus Essentials","https://www.tenable.com/products/nessus/nessus-essentials","course"]],
 terms:{"CVE":"A unique ID for a publicly known vulnerability.","CVSS":"A 0–10 severity score for vulnerabilities.","KEV":"CISA's list of vulnerabilities known to be exploited in the wild.","EPSS":"A probability score of exploitation in the next 30 days.","SLA":"The deadline by which a finding must be fixed.","compensating control":"An alternative safeguard used when the main fix isn't possible yet.","authenticated scan":"A scan that logs in to the system, finding more issues."}}
];
